import{_ as e,o as r,c as d,a as o}from"./app.CYXXef1p.js";const u=JSON.parse('{"title":"Program Operating Model and Ownership Map","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/OPERATING_MODEL.md","filePath":"enterprise/OPERATING_MODEL.md","lastUpdated":1771753292000}'),a={name:"enterprise/OPERATING_MODEL.md"};function n(i,t,s,c,l,h){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="program-operating-model-and-ownership-map" tabindex="-1">Program Operating Model and Ownership Map <a class="header-anchor" href="#program-operating-model-and-ownership-map" aria-label="Permalink to &quot;Program Operating Model and Ownership Map&quot;">​</a></h1><p><strong>Scope:</strong> thegent orchestration platform <strong>Date:</strong> 2026-02-14 <strong>Related:</strong> WP-0005, <code>docs/RUNBOOK.md</code>, <code>docs/research/GOVERNANCE_WP_GAPS.md</code></p><hr><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>This document defines the RACI matrix, ownership assignments, and escalation paths for the thegent orchestration platform. It supports org readiness and clear accountability for operations, governance, and recovery.</p><hr><h2 id="_2-raci-matrix" tabindex="-1">2. RACI Matrix <a class="header-anchor" href="#_2-raci-matrix" aria-label="Permalink to &quot;2. RACI Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>Product Owner</th><th>Tech Lead</th><th>Operator</th><th>Security/Compliance</th><th>Stakeholder</th></tr></thead><tbody><tr><td><strong>Orchestration (run, bg, dag run)</strong></td><td>A</td><td>R</td><td>R</td><td>I</td><td>I</td></tr><tr><td><strong>Policy definition &amp; thresholds</strong></td><td>A</td><td>R</td><td>I</td><td>R</td><td>C</td></tr><tr><td><strong>Override approval (--override)</strong></td><td>A</td><td>I</td><td>R</td><td>C</td><td>I</td></tr><tr><td><strong>Escalation queue (govern escalate)</strong></td><td>A</td><td>I</td><td>R</td><td>C</td><td>I</td></tr><tr><td><strong>Drift detection &amp; sweep</strong></td><td>I</td><td>R</td><td>R</td><td>I</td><td>I</td></tr><tr><td><strong>Audit trail &amp; integrity</strong></td><td>I</td><td>R</td><td>I</td><td>R</td><td>C</td></tr><tr><td><strong>Recovery (reconcile, rollback)</strong></td><td>I</td><td>R</td><td>R</td><td>I</td><td>I</td></tr><tr><td><strong>Data protection &amp; retention</strong></td><td>A</td><td>R</td><td>I</td><td>R</td><td>C</td></tr><tr><td><strong>Contract migration &amp; versioning</strong></td><td>A</td><td>R</td><td>I</td><td>I</td><td>C</td></tr><tr><td><strong>Post-launch observation</strong></td><td>A</td><td>R</td><td>R</td><td>I</td><td>I</td></tr></tbody></table><p><strong>Legend:</strong> R = Responsible, A = Accountable, C = Consulted, I = Informed</p><hr><h2 id="_3-ownership-assignments" tabindex="-1">3. Ownership Assignments <a class="header-anchor" href="#_3-ownership-assignments" aria-label="Permalink to &quot;3. Ownership Assignments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domain</th><th>Owner</th><th>Backup</th><th>Scope</th></tr></thead><tbody><tr><td><strong>Orchestration</strong></td><td>Tech Lead</td><td>Operator</td><td>run, bg, dag, agents, routing</td></tr><tr><td><strong>Governance</strong></td><td>Product Owner</td><td>Security</td><td>policy, override, escalation, data-protection</td></tr><tr><td><strong>Recovery</strong></td><td>Tech Lead</td><td>Operator</td><td>reconcile, rollback, recover, stop</td></tr><tr><td><strong>Observability</strong></td><td>Operator</td><td>Tech Lead</td><td>cockpit, benchmark, drift, KPIs</td></tr><tr><td><strong>Contracts</strong></td><td>Tech Lead</td><td>Product Owner</td><td>conformance, migration, schema versioning</td></tr><tr><td><strong>Compliance</strong></td><td>Security/Compliance</td><td>Product Owner</td><td>audit, retention, evidence</td></tr></tbody></table><hr><h2 id="_4-escalation-paths" tabindex="-1">4. Escalation Paths <a class="header-anchor" href="#_4-escalation-paths" aria-label="Permalink to &quot;4. Escalation Paths&quot;">​</a></h2><h3 id="_4-1-policy-denial-blocked-run" tabindex="-1">4.1 Policy Denial / Blocked Run <a class="header-anchor" href="#_4-1-policy-denial-blocked-run" aria-label="Permalink to &quot;4.1 Policy Denial / Blocked Run&quot;">​</a></h3><ol><li><strong>T0:</strong> Run blocked by policy (e.g. trust score, critical lane, drift budget).</li><li><strong>T0+0:</strong> Run added to escalation queue (<code>thegent govern escalate list</code>).</li><li><strong>SLA:</strong> Resolve within <code>THGENT_ESCALATION_SLA_MINUTES</code> (default 30 min).</li><li><strong>T0+SLA:</strong> If past SLA, escalate to Product Owner.</li><li><strong>Resolution:</strong> <code>thegent govern escalate resolve &lt;run_id&gt;</code> or <code>--override</code> with justification.</li></ol><h3 id="_4-2-contract-drift-adapter-failure" tabindex="-1">4.2 Contract Drift / Adapter Failure <a class="header-anchor" href="#_4-2-contract-drift-adapter-failure" aria-label="Permalink to &quot;4.2 Contract Drift / Adapter Failure&quot;">​</a></h3><ol><li><strong>T0:</strong> Drift detected (<code>thegent observe drift</code>, <code>thegent govern conformance --check-drift</code>).</li><li><strong>T0+0:</strong> Critical lane blocked (XC2); DAG run with <code>--check-drift</code> exits 2.</li><li><strong>SLA:</strong> Investigate within 60 min; remediate within 4 hours.</li><li><strong>Escalation:</strong> Tech Lead → Product Owner if adapter change required.</li></ol><h3 id="_4-3-audit-integrity-failure" tabindex="-1">4.3 Audit / Integrity Failure <a class="header-anchor" href="#_4-3-audit-integrity-failure" aria-label="Permalink to &quot;4.3 Audit / Integrity Failure&quot;">​</a></h3><ol><li><strong>T0:</strong> <code>thegent history verify</code> fails or hash chain broken.</li><li><strong>T0+0:</strong> Escalate immediately to Security/Compliance.</li><li><strong>SLA:</strong> Root cause within 2 hours; remediation per incident severity.</li></ol><h3 id="_4-4-post-launch-incident" tabindex="-1">4.4 Post-Launch Incident <a class="header-anchor" href="#_4-4-post-launch-incident" aria-label="Permalink to &quot;4.4 Post-Launch Incident&quot;">​</a></h3><p>See <code>docs/POST_LAUNCH_OBSERVATION_PLAYBOOK.md</code> for severity→SLA mapping.</p><hr><h2 id="_5-handoff-and-continuity" tabindex="-1">5. Handoff and Continuity <a class="header-anchor" href="#_5-handoff-and-continuity" aria-label="Permalink to &quot;5. Handoff and Continuity&quot;">​</a></h2><ul><li><strong>Shift handoff:</strong> Operator documents active escalations and running sessions in continuity log.</li><li><strong>Ownership transfer:</strong> Incoming owner confirms escalation queue and past-SLA items via <code>thegent govern escalate list --past-sla</code>.</li><li><strong>Runbook reference:</strong> All procedures in <code>docs/RUNBOOK.md</code>; escalation links in §3.</li></ul><hr><h2 id="_6-configuration-code-enforcement" tabindex="-1">6. Configuration (Code Enforcement) <a class="header-anchor" href="#_6-configuration-code-enforcement" aria-label="Permalink to &quot;6. Configuration (Code Enforcement)&quot;">​</a></h2><p>The operating model is enforced via config. These settings map to the escalation paths above:</p><table tabindex="0"><thead><tr><th>Config / Env</th><th>Default</th><th>Maps To</th></tr></thead><tbody><tr><td><code>escalation_sla_minutes</code> / <code>THGENT_ESCALATION_SLA_MINUTES</code></td><td>30</td><td>§4.1 Policy Denial SLA</td></tr><tr><td><code>escalation_sla_breach_alert</code></td><td>true</td><td>§4.1 Past-SLA alert in <code>govern sweep</code></td></tr><tr><td><code>override_ttl_seconds</code></td><td>86400 (24h)</td><td>§4.1 Override validity</td></tr></tbody></table><p><strong>Source:</strong> <code>src/thegent/config.py</code> — <code>ThegentSettings</code></p><hr><h2 id="_7-references" tabindex="-1">7. References <a class="header-anchor" href="#_7-references" aria-label="Permalink to &quot;7. References&quot;">​</a></h2><ul><li><code>docs/RUNBOOK.md</code> — On-call procedures, recovery, escalation</li><li><code>docs/research/GOVERNANCE_WP_GAPS.md</code> — WP-3008 escalation queue</li><li><code>docs/plans/09-RISK-REGISTRY.md</code> — Risk-based SLA targets</li></ul>',33)])])}const p=e(a,[["render",n]]);export{u as __pageData,p as default};
